L000056	\title{Signatures of a subpopulation of hierarchical mergers in the GWTC-4 gravitational-wave dataset}
L000057	
L000058	\author{Cailin Plunkett\,\orcidlink{0000-0002-1144-6708}}\email{caplunk@mit.edu}\ligo\mki\mit
L000059	\author{Thomas Callister\,\orcidlink{0000-0001-9892-177X}}\williams
